		consonantClass: ThaiSymbolClass.Low,
		syllableType: "dead-short",
		resultingTone: "high",
		description:
			"Low class consonant + dead syllable + short vowel = high tone. High tone starts at a high pitch and rises very slightly.",
		lesson: 4,
	},
	// Lesson 5: Low class dead long
	{
		id: "low-dead-long",
		consonantClass: ThaiSymbolClass.Low,
