		feature: "added-stroke",
		detail: "ศ plants an extra flag stroke on top of the ค shape",
	},
	{
		a: "ฆ",
		b: "ม",
		feature: "added-stroke",
		detail: "ฆ adds a bumped curve after the head that ม lacks",
	},
	{
		a: "ช",
