		a: "พ",
		b: "ฬ",
		feature: "added-stroke",
		detail: "ฬ ends in an extra curled tail that พ never grows",
	},
	{
		a: "ล",
		b: "ส",
		feature: "added-stroke",
		detail: "ส crosses the ล shape with an extra line",
	},
	{
		a: "อ",
		b: "ฮ",
		feature: "added-stroke",
		detail: "ฮ wears a zigzag crown over the plain ring of อ",
	},
	{
		a: "ไ",
		b: "ใ",
		feature: "top-ornament",
		detail: "ไ tops out in a zigzag, ใ in a curl",
	},
];

// ----------------------------------------------------------------------------
// Final-sound behaviour
// ----------------------------------------------------------------------------

export type FinalSoundBehaviour =
	| { kind: "final"; sound: string }
	| { kind: "vowel-syllable"; syllable: "live" | "dead" }
	| { kind: "not-applicable" };

// Short vowels whose open syllable is nonetheless live, because the vowel
// carries its own sonorant ending: ำ ends in m, ไ and ใ in the i glide, เ-า
// in the o glide. Everything else derives from length: long open syllables
// are live, short ones dead.
const LIVE_SHORT_VOWELS: readonly string[] = ["ำ", "ไ", "ใ", "เ-า"];

function openSyllableLiveness(vowel: ThaiVowel): "live" | "dead" {
	if (vowel.length === "long") return "live";
	return LIVE_SHORT_VOWELS.includes(vowel.character) ? "live" : "dead";
}

// ----------------------------------------------------------------------------
// The annotation record
// ----------------------------------------------------------------------------

export type AnnotationKind = "consonant" | "vowel" | "tone-mark" | "word";

export interface SceneAnnotation {
	kind: AnnotationKind;
	/** ThaiSymbol.character, or the Thai spelling for a word record. */
	key: string;
	romanizedName: string;
	finalSound: FinalSoundBehaviour;
	/** Sound-type classification; null where the kind has no class at all. */
	classification: Classification | null;
	/** Class district; null for kinds that must not cue a class. */
	district: District | null;
	/** The mnemonic's shape binding. Task 2.4 authors these. */
	shapeCue: string | null;
	/** The mnemonic's sound binding. Task 2.4 authors these. */
	soundCue: string | null;
	carriesTone: boolean;
	/** One of the five shipped motions, named — never contour data. */
	toneMotion: ToneValue | null;
	conditionalForm: ConditionalVowelForm | null;
}

function consonantAnnotation(consonant: ThaiConsonant): SceneAnnotation {
	const classification = classifyConsonant(consonant);
	return {
		kind: "consonant",
		key: consonant.character,
		romanizedName: consonant.nameRomanized,
		finalSound: { kind: "final", sound: consonant.finalSound },
		classification,
		district:
			classification.state === "classified"
				? districtForClass(classification.consonantClass)
				: null,
		shapeCue: null,
		soundCue: null,
		carriesTone: false,
		toneMotion: null,
		conditionalForm: null,
	};
}

function vowelAnnotation(vowel: ThaiVowel): SceneAnnotation {
	return {
		kind: "vowel",
		key: vowel.character,
		romanizedName: vowel.name,
		finalSound: {
			kind: "vowel-syllable",
			syllable: openSyllableLiveness(vowel),
		},
		classification: null,
		district: null,
		shapeCue: null,
		soundCue: null,
		carriesTone: false,
		toneMotion: null,
		conditionalForm: conditionalFormFor(vowel.character),
	};
}

function toneMarkAnnotation(mark: ThaiToneMark): SceneAnnotation {
	return {
		kind: "tone-mark",
		key: mark.character,
		romanizedName: mark.name,
		finalSound: { kind: "not-applicable" },
		classification: null,
		district: null,
		shapeCue: null,
		soundCue: null,
		carriesTone: true,
		// The mark's citation motion is its mid-class effect — the tone it is
		// named for. The full class-dependent table stays on ThaiToneMark.
		toneMotion: mark.midClassTone,
		conditionalForm: null,
	};
}

function wordAnnotation(word: ThaiWord): SceneAnnotation {
	return {
		kind: "word",
		key: word.name,
		romanizedName: word.romanization,
		finalSound: { kind: "not-applicable" },
		classification: null,
		district: null,
		shapeCue: null,
		soundCue: null,
		carriesTone: true,
		toneMotion: word.tone,
		conditionalForm: null,
	};
}

/**
 * One annotation per mnemonic-carrying record in symbols.ts: 44 consonants,
 * 29 vowels, 4 tone marks, and the mnemonic-bearing words — 82 in all. The
 * word and tone-mark records are the nine whose facts have no other home.
 */
export const sceneAnnotations: readonly SceneAnnotation[] = [
	...consonants.map(consonantAnnotation),
	...vowels.map(vowelAnnotation),
	...toneMarks.map(toneMarkAnnotation),
];

const annotationsByKey = new Map(
	sceneAnnotations.map((annotation) => [annotation.key, annotation]),
);

export function annotationFor(key: string): SceneAnnotation | undefined {
	return annotationsByKey.get(key);
}

// ----------------------------------------------------------------------------
// Validation
// ----------------------------------------------------------------------------
// Failures name their fields. A refused record must never look like an empty
// one — the caller gets the exact list of what is missing and what is wrong.

export type Validation =
	| { ok: true }
	| { ok: false; missing: readonly string[]; invalid: readonly string[] };

function verdict(missing: string[], invalid: string[]): Validation {
	return missing.length === 0 && invalid.length === 0
		? { ok: true }
		: { ok: false, missing, invalid };
}

function isBlank(value: string | null | undefined): boolean {
	return value === null || value === undefined || value.trim() === "";
}

/** The loosely-typed shape validation accepts, so deficient records can be checked. */
export interface SceneAnnotationInput {
	kind: AnnotationKind;
	district?: District | null;
	shapeCue?: string | null;
	soundCue?: string | null;
	carriesTone?: boolean;
	toneMotion?: ToneValue | null;
}

/**
 * A record validates only if it binds shape and sound as separate cues, its
 * district where it carries a class, and its tone motion where it carries a
 * tone. A record binding only shape fails, naming the missing fields.
 */
export function validateSceneAnnotation(
	record: SceneAnnotationInput,
): Validation {
	const missing: string[] = [];
	const invalid: string[] = [];

	if (isBlank(record.shapeCue)) missing.push("shapeCue");
	if (isBlank(record.soundCue)) missing.push("soundCue");

	if (record.kind === "consonant") {
		if (!record.district) missing.push("district");
	} else if (record.district) {
		invalid.push(
			"district: only a class-bearing record stages in a class district",
		);
	}

	if (record.carriesTone) {
		if (!record.toneMotion) missing.push("toneMotion");
	} else if (record.toneMotion) {
		invalid.push("toneMotion: only a tone-carrying record encodes a motion");
	}

	return verdict(missing, invalid);
}

export function validateConditionalForm(form: {
	vowel?: string;
	openForm?: string;
	withFinalForm?: string;
}): Validation {
	const missing: string[] = [];
	const invalid: string[] = [];

	if (isBlank(form.vowel)) missing.push("vowel");
	if (isBlank(form.openForm)) missing.push("openForm");
	if (isBlank(form.withFinalForm)) missing.push("withFinalForm");
	if (
		!isBlank(form.openForm) &&
		!isBlank(form.withFinalForm) &&
		form.openForm === form.withFinalForm
	) {
		invalid.push("withFinalForm: declares no change from the open form");
	}

	return verdict(missing, invalid);
}

export function validateConfusablePair(pair: {
	a?: string;
	b?: string;
	feature?: string;
	detail?: string;
}): Validation {
	const missing: string[] = [];
	const invalid: string[] = [];

	if (isBlank(pair.a)) missing.push("a");
	if (isBlank(pair.b)) missing.push("b");
	if (isBlank(pair.feature)) {
		missing.push("feature");
	} else if (
		!(DISTINGUISHING_FEATURES as readonly string[]).includes(
			pair.feature as string,
		)
	) {
		invalid.push(`feature: "${pair.feature}" is not a distinguishing feature`);
	}
	if (!isBlank(pair.a) && pair.a === pair.b) {
		invalid.push("b: a pair must name two different glyphs");
	}

	return verdict(missing, invalid);
}

import { ThaiSymbolClass } from "./symbols";

// ============================================================================
// Sound type — consonant class as a derivable property
// ============================================================================
// Thai consonant class is a phonetic natural class, not an arbitrary list of
// 44 facts:
//
//   sonorant                 → always low   (derived, no memorisation)
//   unaspirated obstruent    → always mid   (derived; this is the whole class)
//   aspirate or fricative    → high or low  (only the 11 high ones are learned)
//
// Everything here reads a consonant's `initialSound` and `isAspirated` and
// NOTHING else. In particular the declared class field is never consulted: a
// derivation that peeked at it would agree with it by construction and could
// never catch the data drifting from the rule the lessons teach.

/** The three phonetic buckets every Thai consonant falls into. */
export type SoundType =
	| "sonorant"
	| "unaspirated-obstruent"
	| "aspirate-or-fricative";

/**
 * The one genuine memorisation load in the class system: the 11 high-class
 * letters. Every one is an aspirated stop or a fricative — the other two
 * buckets never consult this (or any) per-letter table.
 */
export const HIGH_CLASS_CONSONANTS: readonly string[] = [
	"ข",
	"ฃ",
	"ฉ",
	"ฐ",
	"ถ",
	"ผ",
	"ฝ",
	"ศ",
	"ษ",
	"ส",
	"ห",
];

// Phoneme classes, keyed by the leading token of `initialSound`. These are
// definitions of sound types (seven sonorant onsets exist in Thai, and so on),
// not per-letter tables: a glyph never appears here, so any consonant — even
// one this file has never seen — classifies from its sound alone.
const SONORANT_PHONEMES: readonly string[] = [
	"m",
	"n",
	"ng",
	"y",
	"r",
	"l",
	"w",
];
const PLAIN_OBSTRUENT_PHONEMES: readonly string[] = [
	"g",
	"j",
	"d",
	"dt",
	"b",
	"bp",
	// อ, the silent placeholder onset, patterns with the plain stops: it is the
	// ninth member of the mid class.
	"silent",
];
const ASPIRATED_STOP_PHONEMES: readonly string[] = ["kh", "ch", "th", "ph"];
const FRICATIVE_PHONEMES: readonly string[] = ["f", "s", "h"];

/**
 * The leading phoneme token of a stored `initialSound` — the part before the
 * first parenthetical gloss, e.g. `"th (same as ฑ and ท)"` → `"th"`.
 */
export function leadingPhoneme(initialSound: string): string | null {
	const match = initialSound.match(/^([a-z]+)/i);
	return match ? match[1].toLowerCase() : null;
}

/**
 * Whether a consonant with this `initialSound` must carry `isAspirated: true`
 * for the data to be coherent: exactly the aspirated stops kh, ch, th, ph.
 * Fricatives (f, s, h) breathe but are not aspirated stops.
 */
export function expectedAspiration(initialSound: string): boolean {
	const token = leadingPhoneme(initialSound);
	return token !== null && ASPIRATED_STOP_PHONEMES.includes(token);
}

/** The facts classification reads. Deliberately excludes the declared class. */
export interface ConsonantSoundFacts {
	character: string;
	initialSound: string;
	isAspirated: boolean;
}

/**
 * The three states a consonant can be in with respect to classification.
 * `unclassifiable` always carries its reason, so a letter the rule cannot
 * place never reads the same as one nobody has looked at yet.
 */
export type Classification =
	| {
			state: "classified";
			soundType: SoundType;
			consonantClass: ThaiSymbolClass;
	  }
	| { state: "unclassifiable"; reason: string }
	| { state: "unclassified" };

/** The not-yet-attempted state, for consumers tracking classification lazily. */
export const UNCLASSIFIED: Classification = { state: "unclassified" };

type PhonemeKind =
	| "sonorant"
	| "plain-obstruent"
	| "aspirated-stop"
	| "fricative";

function phonemeKind(token: string): PhonemeKind | null {
	if (SONORANT_PHONEMES.includes(token)) return "sonorant";
	if (PLAIN_OBSTRUENT_PHONEMES.includes(token)) return "plain-obstruent";
	if (ASPIRATED_STOP_PHONEMES.includes(token)) return "aspirated-stop";
	if (FRICATIVE_PHONEMES.includes(token)) return "fricative";
	return null;
}

/**
 * Classify a consonant from its sound facts alone.
 *
 * Never returns the `unclassified` state — an input the rule cannot place is
 * reported as `unclassifiable` with the reason, which the return type
 * guarantees.
 */
export function classifyConsonant(
	facts: ConsonantSoundFacts,
): Exclude<Classification, { state: "unclassified" }> {
	const token = leadingPhoneme(facts.initialSound);
	if (token === null) {
		return {
			state: "unclassifiable",
			reason: `initialSound "${facts.initialSound}" has no leading phoneme token`,
		};
	}

	const kind = phonemeKind(token);
	if (kind === null) {
		return {
			state: "unclassifiable",
			reason: `initialSound token "${token}" is not a recognised Thai onset`,
		};
	}

	// The two fields must agree before either is trusted. This is the check
	// that caught ฑ and ฒ shipping as unaspirated while their own initialSound
	// read "th": a derivation that trusted one field silently would have
	// classed both wrong and let the rule take the blame.
	if (kind === "aspirated-stop" && !facts.isAspirated) {
		return {
			state: "unclassifiable",
			reason: `initialSound "${facts.initialSound}" names an aspirated stop but isAspirated is false`,
		};
	}
	if (kind !== "aspirated-stop" && facts.isAspirated) {
		return {
			state: "unclassifiable",
			reason: `isAspirated is true but initialSound token "${token}" is not an aspirated stop`,
		};
	}

	if (kind === "sonorant") {
		return {
			state: "classified",
			soundType: "sonorant",
			consonantClass: ThaiSymbolClass.Low,
		};
	}
	if (kind === "plain-obstruent") {
		return {
			state: "classified",
			soundType: "unaspirated-obstruent",
			consonantClass: ThaiSymbolClass.Mid,
		};
	}

	// Only the aspirate/fricative bucket consults a per-letter list — the
	// 11-member residue that genuinely has to be memorised.
	return {
		state: "classified",
		soundType: "aspirate-or-fricative",
		consonantClass: HIGH_CLASS_CONSONANTS.includes(facts.character)
			? ThaiSymbolClass.High
			: ThaiSymbolClass.Low,
	};
}
